type Temp float64

func (t Temp) MarshalText() ([]byte, error) {
    return []byte(strconv.FormatFloat(float64(t), 'f', 1, 64)), nil
}

func (t *Temp) UnmarshalText(b []byte) error {   // pointer receiver required
    v, err := strconv.ParseFloat(string(b), 64)
    if err != nil { return fmt.Errorf("temp %q: %w", b, err) }
    *t = Temp(v)
    return nil
}
